                        b1.Property<decimal>("Qty")
                            .HasColumnType("numeric")
                            .HasColumnName("qty");

                        b1.Property<decimal>("TaxAmount")
                            .HasColumnType("numeric")
                            .HasColumnName("tax_amount");

                        b1.Property<string>("TaxCodeId")
                            .HasColumnType("text")
                            .HasColumnName("tax_code_id");

                        b1.Property<int?>("TaxCodeVersion")
